using System.Text.Json;
using System.Text.Json.Serialization.Metadata;

// Options that know about standard types via the default resolver
var options = new JsonSerializerOptions(JsonSerializerDefaults.Web);

// ── 1. Strongly-typed metadata (JsonTypeInfo<T>) ──────────────────
// GetTypeInfo returns the non-generic base; cast to the generic form.
var intInfo = (JsonTypeInfo<int>)options.GetTypeInfo(typeof(int));
Console.WriteLine($"1) Got typed metadata : {intInfo.Type.Name}  (kind: {intInfo.Kind})");

string json = JsonSerializer.Serialize(42, intInfo);
Console.WriteLine($"   Round-trip via typed info: {json}");

// ── 2. Probe without throwing (TryGetTypeInfo) ────────────────────
// Succeeds for a type the resolver can handle:
if (options.TryGetTypeInfo(typeof(string), out JsonTypeInfo? stringInfo))
    Console.WriteLine($"2a) string metadata found   : {stringInfo!.Type.Name}");
else
    Console.WriteLine("2a) string metadata NOT found");

// Fails gracefully for a type with no metadata (empty resolver):
var empty = new JsonSerializerOptions { TypeInfoResolver = JsonTypeInfoResolver.Combine() };
if (empty.TryGetTypeInfo(typeof(string), out _))
    Console.WriteLine("2b) string metadata found in empty resolver (unexpected)");
else
    Console.WriteLine("2b) string metadata NOT found in empty resolver — no exception thrown");

